ALTER POLICY location_read ON public.technician_locations USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (user_id=auth.uid() OR (public.my_role() IN ('admin','superuser','supervisor') AND EXISTS(SELECT 1 FROM public.shifts s WHERE s.id=technician_locations.shift_id AND s.company_id=technician_locations.company_id AND s.user_id=technician_locations.user_id AND s.shift_type='shift' AND s.ended_at IS NULL))));
GRANT DELETE ON public.technician_locations TO authenticated;
CREATE POLICY location_delete ON public.technician_locations FOR DELETE TO authenticated USING(user_id=auth.uid() AND company_id=public.current_company_id());
ALTER POLICY receipt_insert ON public.jobsheet_receipts WITH CHECK(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND file_path=company_id::text||'/'||jobsheet_id::text||'/'||id::text||'.pdf' AND EXISTS(SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_receipts.jobsheet_id AND j.company_id=jobsheet_receipts.company_id AND j.status<>'completed'));
ALTER POLICY technical_insert ON public.technical_documents WITH CHECK(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND (public.my_role() IN ('superuser','supervisor') OR (public.my_role()='technician' AND status='pending' AND NOT restricted)));
CREATE POLICY technical_own_pending_cleanup ON public.technical_documents FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND status='pending' AND public.member_is_active(auth.uid()));
CREATE POLICY receipt_own_pending_cleanup ON public.jobsheet_receipts FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.job_sheets j WHERE j.id=jobsheet_receipts.jobsheet_id AND j.status<>'completed'));
CREATE TRIGGER technical_delete_commercial BEFORE DELETE ON public.technical_documents FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_write('core');
CREATE TRIGGER location_commercial BEFORE INSERT OR UPDATE ON public.technician_locations FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_write('core');